-- Generated by `engine types sync` from types/*.toml (postgres).
-- create type `note`

CREATE TABLE content_note (
    id bigserial PRIMARY KEY,
    slug text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND length(slug) <= 80),
    status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published')),
    version integer NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    published_at timestamptz,
    "title" text,
    "body" text
);
CREATE TRIGGER content_note_changes
    AFTER INSERT OR UPDATE OR DELETE ON content_note
    FOR EACH ROW EXECUTE FUNCTION engine_record_change('note');
CREATE INDEX IF NOT EXISTS content_note_published_newest ON content_note ((COALESCE(published_at, created_at)) DESC, id DESC) WHERE status = 'published';
